css:
:root { --paper:#f4f4f1; --ink:#1b1f30; --hand:#1f2d66; --muted:#5d6272; --flare:#c8306c; --rule:#c6c6c0; --bubble:rgba(27,31,48,.075); --focus:#1f2d66; color-scheme:light; }
