:root[data-theme="dark"] { --paper:#12142a; --ink:#e9e4d6; --hand:#d6ddff; --muted:#9c9fb4; --flare:#ff6fae; --rule:#33365a; --bubble:rgba(233,228,214,.085); --focus:#ff6fae; color-scheme:dark; }
html { background:var(--paper); color:var(--ink); -webkit-text-size-adjust:100%; }
