:focus-visible { outline:2px solid var(--focus); outline-offset:3px; border-radius:2px; }
em, i, cite { font-style:italic; }
sup { line-height:0; font-size:.72em; vertical-align:.55em; }
p { margin:0 0 1.6em; }
p + p { text-indent:1.5em; }
.no-indent, .chat p, li p { text-indent:0; }
h2, h3, h4 { font-weight:500; line-height:1.3; margin:2.6em 0 1em; }
h2 { font-size:1.35em; } h3 { font-size:1.15em; } h4 { font-size:1em; }
blockquote { margin:2.2em 0 2.4em 2.2em; padding:0; }
blockquote p { text-indent:0; } blockquote p + p { margin-top:.9em; }
ul, ol { padding-left:1.6em; } li { margin:0 0 .6em; }
img, svg, video { max-width:100%; height:auto; }
pre, table { overflow-x:auto; max-width:100%; display:block; }
.sans, .byline, .credit, .controls, .colophon, .notes h2, .chat { font-family:"IBM Plex Sans",system-ui,-apple-system,"Segoe UI",Helvetica,Arial,sans-serif; }
.right { text-align:right; } .center { text-align:center; }
.frame { color:var(--hand); }
.chat { font-size:.9em; line-height:1.75; overflow-wrap:anywhere; margin:2.4em 0 2.6em; }
