h1 { font-weight:400; font-size:clamp(1.7rem,1.3rem + 2vw,2.5rem); line-height:1.2; margin:0 0 .9rem; color:var(--hand); }
.byline { margin:0 0 .25rem; font-size:1rem; font-weight:500; letter-spacing:.01em; }
.credit { margin:0; font-size:.86rem; color:var(--muted); }
.controls { margin:2rem 0 0; font-size:.82rem; display:flex; flex-wrap:wrap; gap:.5rem 1.4rem; }
.controls button { font:inherit; color:var(--muted); background:none; border:0; padding:0; cursor:pointer; border-bottom:1px solid var(--rule); line-height:1.5; }
.controls button:hover { color:var(--flare); border-bottom-color:var(--flare); }
.no-js .controls { display:none; }
.epigraph { margin:0 0 2.2em; } .epigraph p { text-indent:0; }
