.js:not(.typed) ol, .js:not(.typed) ul, .js:not(.typed) .notes ol { list-style:none; padding-left:0; }
.chat > div + div { margin-top:1.1em; }
.js:not(.typed) .fn-num { display:inline; } .fn-num { display:none; }
.notes { margin-top:7rem; font-size:.9em; }
.notes h2 { font-size:.8rem; font-weight:500; letter-spacing:.04em; color:var(--muted); margin:0 0 .8em; }
.notes ol { padding-left:1.6em; margin:0; } .notes li p { text-indent:0; }
.colophon { margin-top:5rem; padding-top:1.2rem; border-top:1px solid var(--rule); font-size:.8rem; color:var(--muted); }
.colophon p { margin:0 0 .5em; text-indent:0; } .colophon a { color:var(--muted); }
:target { scroll-margin-top:2rem; }
@media print { .hand-svg, .controls { display:none; } .hand-src { position:static !important; width:auto !important; height:auto !important; clip:auto !important; clip-path:none !important; white-space:normal !important; } }

